// Typed view of the course site data, generated by `tutor site-data` from
// course/courses/*.toml, course/units/*.toml and the recorded outputs in
// course/outputs/: site/data/courses.json (the courses, no unit content) and
// one site/data/course-<id>.json per course. Reference solutions and generated
// test cases are not in them: grading happens in the learner's own Julia via
// `tutor serve`.
import index from "../../site/data/courses.json";

const courseFiles = import.meta.glob("../../site/data/course-*.json", { eager: true, import: "default" });

export interface Example {
  code: string;
  caption: string; // introduces the example (shown above the code)
  notice: string; // what to look at in the result (shown under the output); "" for none
  mode: "repl" | "file";
  check: boolean;
  output: string | null; // null: not recorded yet
  ok: boolean | null;
  images: string[]; // recorded figures, as site paths (assets/figures/<unit>/<file>)
  predict?: Prediction; // commit a prediction before the output is shown (see predict.ts); absent for most examples
  choose?: Checkpoint; // pick a method and give a reason before the output is shown (see choose.ts)
  breakit?: BreakIt; // find where the method fails before the sweep is shown (see breakit.ts)
}

/**
 * A break-it challenge. `rows` and `edge` were read from the recorded sweep by
 * `tutor site-data` (only when `tutor course verify` would accept them):
 * nothing here is typed by an author. `m` is text because a measurement may be
 * `Inf` or `NaN`.
 */
export interface BreakIt {
  kc: string;
  prompt: string;
  param: string;
  measure: string;
  fails: "above" | "below";
  limit: number;
  close: number;
  edge: [number, number];
  /** "high": values above the edge fail; "low": values below it fail */
  side: "high" | "low";
  /** the probe's code, with `{{p}}` where the value goes */
  probe: string;
  /** the row regex (named groups `p` and `m`), to read a probe's output */
  row: string;
  explain: string;
  short: string;
  past: string;
  rows: { p: number; m: string; failed: boolean }[];
}

export type ChoiceVerdict = "good" | "costly" | "fails";

/**
 * A method-choice checkpoint. The table (`costs`, `ok`, `ratios`, `verdicts`,
 * one entry per choice) is measured: `tutor site-data` reads it from the
 * recorded output with the author's row regexes and exports the checkpoint
 * only when the measured good set is the declared one, with every ratio well
 * clear of the band's edge (src/course.jl, `checkpoint_output_problems`).
 */
export interface Checkpoint {
  kc: string;
  prompt: string;
  choices: string[];
  cost: string; // what the cost counts
  band: number; // good = within `band` times the cheapest choice that meets the accuracy
  explain: string;
  misconceptions: string[]; // one per choice; "" for a good one
  costs: number[];
  ok: boolean[]; // meets the accuracy the example asks for
  ratios: number[]; // cost / cheapest acceptable cost (3 digits)
  verdicts: ChoiceVerdict[];
}

/**
 * A prediction on an example. `answer` is the choice the recorded output
 * selects (read from it by `tutor course verify`, not typed); `measured` is
 * the value it was read from, shown with the output.
 */
export interface Prediction {
  kc: string;
  prompt: string;
  choices: string[];
  answer: number; // 1-based
  explain: string;
  measured: string;
}

/**
 * A concept question after a section. For kind "output" the right choice is
 * the recorded output of `code` (checked by `tutor course verify`).
 * misconceptions[i] is the feedback for choice i ("" for the answer).
 */
export interface Question {
  kind: "choice" | "output";
  prompt: string;
  code: string;
  choices: string[];
  answer: number; // 1-based
  explain: string;
  misconceptions: string[];
}

export interface Section {
  title: string;
  body: string;
  examples: Example[];
  questions: Question[];
}

export interface Sample {
  call: string;
  result: string;
}

export interface Problem {
  id: string;
  title: string;
  difficulty: "warm-up" | "core" | "stretch";
  kcs: string[];
  prompt: string;
  entry: string;
  starter: string;
  hints: string[];
  samples: Sample[];
  compare: "isequal" | "isapprox";
  rtol: number;
  check_type: boolean;
  random_cases: boolean;
  perf: { sizes: number[]; mutates: boolean } | null;
}

export type Track = "foundations" | "core" | "advanced" | "ecosystem" | "scicomp" | "sciml";

export interface Unit {
  id: string;
  title: string;
  track: Track;
  /** the course the unit belongs to (unit ids are unique across courses) */
  course: string;
  env: string;
  status: "ready" | "planned";
  summary: string;
  kcs: string[];
  prerequisites: string[];
  outline: string[];
  lessons: string[];
  sections: Section[];
  problems: Problem[];
}

export type CourseStatus = "ready" | "in-progress" | "planned";

export interface Outcome {
  text: string;
  /** units of the course, "project:<p>" or "guided:<p>" */
  assessed_by: string[];
  /** cases and programs that will assess it, not built yet */
  planned: string[];
}

export interface CourseInfo {
  id: string;
  title: string;
  order: number;
  status: CourseStatus;
  /** why a course is not ready ("" when it is); shown with its status */
  status_note: string;
  summary: string;
  requires: string[];
  envs: string[];
  units: string[];
  projects: string[];
  guided: string[];
  problems: number;
  outcomes: Outcome[];
  /** computed by `Course.time_estimate` from counts at guessed rates: never a measurement */
  estimate: { low_hours: number; high_hours: number; basis: string };
  /** what `tutor sandbox pull <id>` downloads, and where that was measured */
  setup: { download: string; measured: string };
}

export interface CourseData {
  julia: string;
  generated_by: string;
  tracks: Track[];
  /** whole earlier tracks a track assumes */
  track_requires: Partial<Record<Track, Track[]>>;
  /** in order */
  courses: CourseInfo[];
  /** every unit of every course, in syllabus order */
  units: Unit[];
  envs: Record<string, { name: string; version: string }[]>;
}

interface CourseFile {
  course: string;
  units: Unit[];
}

/**
 * The whole course from the index and the per-course files: units in the
 * index's course order. A course file that is missing, or names a course the
 * index does not list, is an error (the site data is generated, so this only
 * happens if it is stale).
 */
export function assembleCourse(idx: Omit<CourseData, "units">, files: CourseFile[]): CourseData {
  const byCourse = new Map(files.map((f) => [f.course, f]));
  for (const f of files)
    if (!idx.courses.some((c) => c.id === f.course)) throw new Error(`course file for unknown course ${f.course}`);
  const units = idx.courses.flatMap((c) => {
    const f = byCourse.get(c.id);
    if (!f) throw new Error(`no course file for ${c.id}: run tutor site-data`);
    return f.units;
  });
  return { ...idx, courses: [...idx.courses].sort((a, b) => a.order - b.order), units };
}

export const course: CourseData = assembleCourse(
  index as unknown as Omit<CourseData, "units">,
  Object.values(courseFiles) as unknown as CourseFile[],
);

/** The course a unit belongs to. */
export const courseOf = (unitId: string): CourseInfo | undefined =>
  course.courses.find((c) => c.units.includes(unitId));

export const courseById = (id: string): CourseInfo | undefined => course.courses.find((c) => c.id === id);

/** The course's landing page (site/course-<id>.qmd). */
export const landingHref = (id: string) => `course-${id}.html`;

/** A unit page in the syllabus view. */
export const unitHref = (unitId: string) => `course.html?unit=${encodeURIComponent(unitId)}`;

/** "" for a ready course; otherwise the words every mention of the course carries. */
export function statusNote(c: Pick<CourseInfo, "status">): string {
  return c.status === "in-progress" ? "in progress" : c.status === "planned" ? "planned" : "";
}

/** "about 22–50 hours (estimate)": always says it is an estimate. */
export const estimateText = (c: CourseInfo) =>
  `about ${c.estimate.low_hours}–${c.estimate.high_hours} hours (estimate)`;

/**
 * Units of other courses this course's units build on, grouped by course in
 * course order: what a learner needs from elsewhere besides whole courses.
 */
export function crossPrerequisites(c: CourseInfo, units: Unit[] = course.units): { course: CourseInfo; units: string[] }[] {
  const mine = new Set(c.units);
  const needed = new Set<string>();
  for (const u of units) if (mine.has(u.id)) for (const p of u.prerequisites) if (!mine.has(p)) needed.add(p);
  return course.courses
    .filter((o) => o.id !== c.id)
    .map((o) => ({ course: o, units: o.units.filter((id) => needed.has(id)) }))
    .filter((g) => g.units.length > 0);
}

export const TRACK_LABEL: Record<Track, string> = {
  foundations: "Foundations",
  core: "Core language",
  advanced: "Advanced",
  ecosystem: "Ecosystem",
  scicomp: "Scientific computing",
  sciml: "Scientific ML",
};

export const TRACK_BLURB: Record<Track, string> = {
  foundations: "Syntax and everyday tools, from your first expression to broadcasting.",
  core: "Types, dispatch, errors, iteration, modules and I/O: how Julia programs are built.",
  advanced: "Performance, generic code, metaprogramming, interfaces, concurrency and the compiler.",
  ecosystem: "The standard library and the packages Julia is used for, in pinned environments.",
  scicomp: "Numerical methods you can trust: conditioning, error control, linear solvers, DAEs, stochastic models, constrained optimization and parallel limits.",
  sciml: "Differential equations with learned parts: sensitivities, adjoints, neural and universal ODEs, SINDy and PINNs.",
};

/** "Assumes Foundations, Core language, Advanced and Ecosystem", or null. */
export function trackRequirement(t: Track): string | null {
  const req = course.track_requires?.[t];
  if (!req || req.length === 0) return null;
  const names = req.map((r) => TRACK_LABEL[r]);
  const list = names.length === 1 ? names[0] : `${names.slice(0, -1).join(", ")} and ${names[names.length - 1]}`;
  return `Assumes the ${list} tracks; each unit names the earlier units it builds on.`;
}

/**
 * Where a learner stands on one question, from the choices picked so far (in
 * order, 1-based). Wrong picks are kept so each shows its misconception; the
 * question is settled once the answer is picked. Only a right first pick
 * counts as "first-try".
 */
export function questionState(q: Question, picks: number[]) {
  const solvedAt = picks.indexOf(q.answer);
  return {
    done: solvedAt >= 0,
    firstTry: solvedAt === 0,
    wrong: (solvedAt >= 0 ? picks.slice(0, solvedAt) : picks).filter((p) => p !== q.answer),
  };
}

/** Unit number from its id ("05-functions" -> "05"). */
export const unitNumber = (id: string) => id.split("-")[0];

export function findProblem(id: string): { unit: Unit; problem: Problem } | null {
  for (const unit of course.units)
    for (const problem of unit.problems) if (problem.id === id) return { unit, problem };
  return null;
}
